"use strict";(self.webpackChunkexpose_etude=self.webpackChunkexpose_etude||[]).push([[7832],{4061:(e,n,s)=>{s.r(n),s.d(n,{assets:()=>a,contentTitle:()=>u,default:()=>c,frontMatter:()=>t,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"Discours-Publics/Plans/128","title":"PLAN N\xb0128 : L\u2019enfer est-\u200bil r\xe9ellement un lieu de flammes et de tourments ?","description":"Pr\xe9sentation Discours 128","source":"@site/docs/Discours-Publics/Plans/128.md","sourceDirName":"Discours-Publics/Plans","slug":"/Discours-Publics/Plans/128","permalink":"/exposes/docs/Discours-Publics/Plans/128","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/Discours-Publics/Plans/128.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"PLAN N\xb041 : \xab Restez immobiles et voyez comment J\xe9hovah va agir pour vous sauver \xbb","permalink":"/exposes/docs/Discours-Publics/Plans/041"},"next":{"title":"PLAN N\xb0129 : La Bible enseigne-t-\u200belle la Trinit\xe9 ?","permalink":"/exposes/docs/Discours-Publics/Plans/129"}}');var r=s(4848),l=s(8453);const t={},u="PLAN N\xb0128 : L\u2019enfer est-\u200bil r\xe9ellement un lieu de flammes et de tourments ?",a={},d=[{value:"POURQUOI S\u2019INTERESSER A L\u2019ENFER \xb4 ` (3 mn)",id:"pourquoi-sinteresser-a-lenfer---3-mn",level:2},{value:"QUELLE EST LA CONDITION DES MORTS ? (5 mn)",id:"quelle-est-la-condition-des-morts--5-mn",level:2},{value:"QU\u2019EST-CE QUE L\u2019ENFER ? (5 mn)",id:"quest-ce-que-lenfer--5-mn",level:2},{value:"POURQUOI TANT D\u2019OPINIONS DIFFERENTES A PROPOS DE L\u2019ENFER ? \xb4 ` (17 mn)",id:"pourquoi-tant-dopinions-differentes-a-propos-de-lenfer----17-mn",level:2},{value:"QUEL ESPOIR Y A-T-IL POUR CEUX QUI SONT EN ENFER ? (12 mn)",id:"quel-espoir-y-a-t-il-pour-ceux-qui-sont-en-enfer--12-mn",level:2},{value:"QUE DEVONS-NOUS FAIRE ? (3 mn)",id:"que-devons-nous-faire--3-mn",level:2}];function o(e){const n={a:"a",br:"br",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"plan-n128--lenfer-est-il-r\xe9ellement-un-lieu-de-flammes-et-de-tourments-",children:"PLAN N\xb0128 : L\u2019enfer est-\u200bil r\xe9ellement un lieu de flammes et de tourments ?"})}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.a,{href:"/exposes/docs/Discours-Publics/Pr%C3%A9sentation/N-128_L-enfer-est-il-reelement-un-lieu-de-flammes-et-de-tourments",children:"Pr\xe9sentation Discours 128"})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"REMARQUE"})," :"]}),"\n",(0,r.jsx)(n.p,{children:"On montrera que J\xe9hovah, Dieu d\u2019amour, a pris les mesures n\xe9cessaires pour r\xe9tablir de bonnes relations entre lui et l\u2019humanit\xe9 ob\xe9issante. On ne tournera pas en ridicule la doctrine des tourments \xe9ternels, mais on aidera chaleureusement l\u2019auditoire \xe0 raisonner sur la base des enseignements clairs de la Bible."}),"\n",(0,r.jsx)(n.h2,{id:"pourquoi-sinteresser-a-lenfer---3-mn",children:"POURQUOI S\u2019INTERESSER A L\u2019ENFER \xb4 ` (3 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Notre conception de l\u2019enfer influe sur la fa\xe7on dont nous consid\xe9rons Dieu et sur nos relations avec lui."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Notons qu\u2019en 1999, le pape Jean-Paul II a d\xe9clar\xe9 que le mot \u201c enfer \u201d d\xe9signe, non pas un lieu, mais \u201c la situation de celui qui, librement et d\xe9finitivement, s\u2019\xe9loigne de Dieu \u201d. (g00 8/3 29.)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Pourtant, tant \xe0 l\u2019int\xe9rieur qu\u2019\xe0 l\u2019ext\xe9rieur de la chr\xe9tient\xe9, de nombreuses personnes croient que l\u2019enfer est un endroit o\xf9 les m\xe9chants subissent une punition \xe9ternelle et o\xf9, d\u2019apr\xe8s certains, ils sont tourment\xe9s par le feu (rs 123)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"C\u2019est une crainte morbide, et non l\u2019amour, qui risque de pousser ceux qui adh\xe8rent \xe0 une telle croyance \xe0 servir Dieu (1Jn 4:18, 19)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Cette croyance peut nous dissuader de vouloir nous approcher de Dieu (Jc 4:8)."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Pour conna\xeetre la v\xe9rit\xe9 au sujet de l\u2019enfer, il nous faut r\xe9pondre aux questions suivantes :"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Quelle est la condition des morts ?"}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Qu\u2019est-\u200bce que l\u2019enfer, et pourquoi les opinions diff\xe8rent-\u200belles autant \xe0 son sujet ?"}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Quel espoir y a-\u200bt-\u200bil pour ceux qui sont en enfer ?"}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"quelle-est-la-condition-des-morts--5-mn",children:"QUELLE EST LA CONDITION DES MORTS ? (5 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Les H\xe9breux des temps bibliques ne croyaient pas qu\u2019une personne demeurait consciente apr\xe8s sa mort."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ils croyaient au contraire que toutes les fonctions vitales s\u2019arr\xeataient (Ps 146:4 ; Ec 9:5, 10 ; rs 253)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Lorsqu\u2019Adam a p\xe9ch\xe9, sa punition a \xe9t\xe9, non pas de subir des tourments \xe9ternels, mais un retour \xe0 l\u2019\xe9tat de non-existence (Gn 2:17 ; 3:19)."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Quand une personne meurt, aucune \xe2me distincte du corps ne s\u2019en va dans un quelconque royaume des morts."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"La Bible enseigne tout simplement que l\u2019\xe2me, ou la personne, meurt (Is 53:12 ; \xc9z 18:4)."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"quest-ce-que-lenfer--5-mn",children:"QU\u2019EST-CE QUE L\u2019ENFER ? (5 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Dans de nombreuses traductions de la Bible, \u201c enfer \u201d est employ\xe9 pour rendre le mot h\xe9breu sh\xe9ol et le mot grec had\xe8s (it-1 763 ; it-2 970)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Un lexique h\xe9breu (A Compendious Hebrew Lexicon) affirme que le sh\xe9ol est \u201c le r\xe9ceptacle, ou r\xe9gion, des morts \u201d. (it-2 969.)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Par cons\xe9quent, l\u2019enfer est la tombe commune aux humains, et non un lieu de flammes et de tourments (it-1 1061)."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Adam ayant p\xe9ch\xe9, \xe0 leur mort ses descendants s\u2019en vont dans l\u2019enfer biblique, la tombe, o\xf9 il n\u2019y a plus ni vie ni conscience (Rm 5:12)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Puisque l\u2019enfer n\u2019est que la tombe, c\u2019est l\xe0 qu\u2019\xe0 leur mort vont tous les humains, les bons comme les m\xe9chants (Gn 37:35 ; Jb 14:13 ; Ac 2:25-27)."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"pourquoi-tant-dopinions-differentes-a-propos-de-lenfer----17-mn",children:"POURQUOI TANT D\u2019OPINIONS DIFFERENTES A PROPOS DE L\u2019ENFER ? \xb4 ` (17 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Des pa\xefens pr\xe9chr\xe9tiens ont invent\xe9 la doctrine des tourments apr\xe8s la mort (rs 129)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"On trouve des preuves de l\u2019existence d\u2019une croyance en un enfer de feu dans la religion de l\u2019\xc9gypte antique."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Dans les croyances babylonienne et assyrienne des temps antiques, le royaume des morts est d\xe9peint comme un lieu plein d\u2019horreurs."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Le bouddhisme, qui remonte au VIe si\xe8cle avant notre \xe8re, enseigne l\u2019existence d\u2019un enfer br\xfblant et d\u2019un enfer froid."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La Bible ne parle-\u200bt-\u200belle pas de \u201c la g\xe9henne de feu \u201d ? (Mt 5:22 ; rs 127.)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Les \xc9critures grecques chr\xe9tiennes mentionnent \xe0 12 reprises la g\xe9henne, et ce mot est souvent associ\xe9 au feu."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Par exemple, J\xe9sus a parl\xe9 de jeter \u2018 tout le corps \u2019 de quelqu\u2019un dans la g\xe9henne (Mt 5:29, 30)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Il a \xe9galement exhort\xe9 ses disciples \xe0 craindre \u201c celui qui peut d\xe9truire et l\u2019\xe2me et le corps dans la g\xe9henne \u201d. (Mt 10:28.)"}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La vall\xe9e de Hinnom (g\xe9henne) \xe9tait situ\xe9e \xe0 l\u2019ext\xe9rieur des murs de J\xe9rusalem et elle \xe9tait le th\xe9\xe2tre d\u2019un horrible culte idol\xe2trique qui comprenait des sacrifices d\u2019enfants."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Au Ier si\xe8cle de notre \xe8re, la g\xe9henne \xe9tait utilis\xe9e comme incin\xe9rateur pour les d\xe9tritus de J\xe9rusalem, et on y jetait \xe9galement les corps des animaux morts ainsi que ceux des criminels qui avaient \xe9t\xe9 ex\xe9cut\xe9s."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Les vivants n\u2019y \xe9tant pas jet\xe9s, la g\xe9henne n\u2019est pas un lieu de flammes et de tourments, mais un symbole appropri\xe9 de la destruction \xe9ternelle."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La Bible ne parle-\u200bt-\u200belle pas de tourments avec \u201c du feu et du souffre \u201d ? (R\xe9 14:9-11 ; 20:10.)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Les morts \xe9tant inconscients, il ne peut s\u2019agir que d\u2019un symbole."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Dans la Bible, les \u2018 tourments \u2019 peuvent provenir d\u2019une humiliation (R\xe9 11:10 ; rs 126-7)."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"D\u2019autres personnes voient mati\xe8re \xe0 controverse dans la parabole de J\xe9sus mettant en sc\xe8ne un homme riche qui \u201c se trouvait dans les tourments \u201d dans l\u2019had\xe8s (\u201c enfer \u201d, Crampon) (Lc 16:23)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ce r\xe9cit est-\u200bil \xe0 prendre au sens litt\xe9ral, ou bien s\u2019agit-\u200bil d\u2019un exemple de quelque chose d\u2019autre ?"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Dans une note, la Bible de J\xe9rusalem admet qu\u2019il s\u2019agit d\u2019une \u201c histoire-parabole, sans aucune attache historique \u201d. (rs 128-9.)"}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Que repr\xe9sente cette parabole (rs 129) ?"}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"L\u2019homme riche repr\xe9sente les Pharisiens (Lc 16:14, 22)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Lazare repr\xe9sente les Juifs du commun peuple qui se sont repentis et sont devenus disciples de J\xe9sus (Mt 21:28-32)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Leur mort marque un changement de condition (Lc 16:16)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ceux qui \xe9taient autrefois m\xe9pris\xe9s re\xe7oivent une position de faveur devant Dieu."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ceux qui semblaient approuv\xe9s sont tourment\xe9s par les messages de jugement transmis par ceux qu\u2019ils m\xe9prisaient (Ac 5:33 ; 7:54)."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Des traducteurs de la Bible ont laiss\xe9 leurs croyances personnelles influencer leur travail et n\u2019ont pas \xe9t\xe9 cons\xe9quents dans leur fa\xe7on de rendre les termes sh\xe9ol et had\xe8s (rs 125 ; it-1 763)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La doctrine de l\u2019enfer de feu, qui d\xe9shonore Dieu, tire ses racines beaucoup plus profond\xe9ment que dans les id\xe9es humaines (rs 129)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Satan le Diable, que J\xe9sus a surnomm\xe9 \u201c le p\xe8re du mensonge \u201d, a conspir\xe9 pour calomnier le Dieu d\u2019amour, cherchant \xe0 le faire passer pour un personnage cruel et vindicatif (Jn 8:44)."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"quel-espoir-y-a-t-il-pour-ceux-qui-sont-en-enfer--12-mn",children:"QUEL ESPOIR Y A-T-IL POUR CEUX QUI SONT EN ENFER ? (12 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La doctrine des tourments \xe9ternels est incompatible avec la personnalit\xe9 de Dieu (Jr 7:31 ; rs 128)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La peine pour le p\xe9ch\xe9, c\u2019est la mort (Rm 6:23)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"\xc9tant donn\xe9 que celui qui meurt est quitte de son p\xe9ch\xe9, il ne serait pas conforme \xe0 la justice divine de lui faire subir des tourments \xe9ternels (Dt 32:4 ; Rm 6:7)."}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Le jugement de Dieu \xe0 l\u2019\xe9gard de l\u2019humanit\xe9 aura lieu lors de l\u2019\xe9preuve finale, apr\xe8s le R\xe8gne mill\xe9naire de J\xe9sus Christ (R\xe9 20:7-9, 12, 13 ; rs 326)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"J\xe9hovah, le Dieu d\u2019amour, effacera toutes les douleurs pass\xe9es (H\xe9 2:14 ; rs 377 ; dg 27-8)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ceux qui se trouvent en enfer seront relev\xe9s, et la mort adamique et le sh\xe9ol (had\xe8s) seront d\xe9truits (R\xe9 20:13-15 ; it-2 970)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La r\xe9surrection terrestre de ceux qui se trouvent dans la tombe leur permettra de jouir des bienfaits curatifs de la domination de Christ."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"On leur enseignera la v\xe9rit\xe9 et ils se verront offrir la possibilit\xe9 de vivre \xe9ternellement dans le Paradis (Lc 23:43 ; Ac 24:15)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"La terre sera un paradis, comme elle \xe9tait cens\xe9e le devenir au d\xe9part (Gn 1:28 ; rs 275)."}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Satan, ses d\xe9mons et tous ceux qui se rebellent volontairement contre Dieu seront d\xe9truits \xe0 jamais (R\xe9 20:7-10)."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.h2,{id:"que-devons-nous-faire--3-mn",children:"QUE DEVONS-NOUS FAIRE ? (3 mn)"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Dieu a permis aux humains d\u2019attester qu\u2019il est un Dieu d\u2019amour, et non un Dieu qui fait souffrir (jv 10-12)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"J\xe9hovah nous a offert le privil\xe8ge de devenir ses t\xe9moins."}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:"Ceux qui ont \xe9t\xe9 asservis par la doctrine des tourments apr\xe8s la mort doivent se rapprocher de Dieu et suivre son Fils (Mt 28:19, 20)."}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Ainsi, ils seront lib\xe9r\xe9s de la crainte que suscite cette doctrine d\xe9shonorante qui laisse entendre que J\xe9hovah tourmente les d\xe9funts, que la mort a acquitt\xe9 de leurs p\xe9ch\xe9s."}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"TEMPS IMPARTI : 45 MINUTES"}),(0,r.jsx)(n.br,{}),"\n","\xa9 2002 Watch Tower Bible and Tract Society of Pennsylvania",(0,r.jsx)(n.br,{}),"\n","S-34-F No 128 11/00"]})]})}function c(e={}){const{wrapper:n}={...(0,l.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(o,{...e})}):o(e)}},8453:(e,n,s)=>{s.d(n,{R:()=>t,x:()=>u});var i=s(6540);const r={},l=i.createContext(r);function t(e){const n=i.useContext(l);return i.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function u(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:t(e.components),i.createElement(l.Provider,{value:n},e.children)}}}]);